#!/usr/bin/env python3
"""Depth pass for the institutional academic-library reference pages."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

import enhance_academic_reference_v400 as base
import publish_academic_library_v326 as academic

VERSION = 401
MIN_WORDS = 1000


def appendix(section_slug: str, item: dict) -> str:
    title = base.e(item["title"])
    if section_slug == "branches":
        content = f"""<p><b>طريقة الاستخدام المرجعي:</b> تبدأ قراءة «{title}» بتحديد ما إذا كان المقصود مجالًا بحثيًا، أو تخصصًا مهنيًا، أو عدسة تفسيرية، أو خدمة مؤسسية. هذه المستويات قد تتقاطع لكنها ليست مترادفة. وجود بحوث في المجال لا يمنح تلقائيًا صلاحية ممارسة مهنة منظمة، ووجود جمعية مهنية لا يعني توحيد متطلبات الترخيص بين الدول.</p><p><b>بناء الخريطة العلمية:</b> اجمع بين تعريف المفاهيم، والنظريات المتنافسة، وأدوات القياس، وتصميمات البحث، والنتائج التطبيقية. اسأل عن الفرضية التي يمكن لكل نظرية اختبارها، وما البيانات التي قد تدحضها، وهل أُعيدت النتائج في عينات وثقافات ومختبرات مستقلة. النظريات الواسعة مفيدة للتنظيم، لكنها تحتاج مؤشرات قابلة للقياس حتى لا تصبح تفسيرًا بعديًا لكل نتيجة.</p><p><b>تقييم الدراسات:</b> لا تبدأ من الخلاصة الصحفية. راجع السكان وطريقة الاختيار وحجم العينة وصلاحية القياس وخطة التحليل والبيانات المفقودة وحجم الأثر وفاصل الثقة. في الدراسات الرصدية افحص الإرباك والاتجاه العكسي؛ وفي التجارب افحص العشوائية والانحرافات والانسحاب؛ وفي الدراسات النوعية افحص العينة والسياق وانعكاسية الباحث وشفافية التحليل.</p><p><b>الانتقال إلى التطبيق:</b> حدد المشكلة التشغيلية والبدائل والموارد والنتائج المقصودة وغير المقصودة. لا تحول متوسطًا جماعيًا إلى قرار فردي، ولا تستخدم تصنيفًا نفسيًا لتبرير الاستبعاد. اختبر التطبيق تدريجيًا، واجمع بيانات خط أساس ومتابعة، واطلب رأي المستفيدين، وافحص اختلاف الأثر حسب اللغة والجنس والعمر والقدرة والوضع الاجتماعي.</p><p><b>القراءة المقارنة:</b> قارن «{title}» بالفروع المجاورة على خمسة محاور: السؤال المركزي، ووحدة التحليل، والأدوات، ونوع الاستنتاج، ونطاق الممارسة. هذا يمنع تكرار الصفحات ويكشف متى يكون الاختلاف في المصطلح فقط ومتى يعكس اختلافًا جوهريًا في المنهج أو الهدف.</p><p><b>معيار الاعتماد المؤسسي:</b> لا تعتمد المادة للتدريب أو السياسة قبل مراجعة مختص مستقل، وتوثيق المصادر، وإظهار تضارب المصالح، وتحديد دورة تحديث، وإتاحة التصحيح. ويجب أن تظل الصفحة قابلة للتعديل عند ظهور دليل أقوى أو تغير المعايير المهنية.</p>"""
    elif section_slug == "therapies":
        content = f"""<p><b>بطاقة تقييم العلاج:</b> لفهم «{title}» لا يكفي سؤال: هل ينجح؟ يجب تحديد لمن، وبأي صيغة، ومقارنة بماذا، ولأي نتيجة، وخلال أي مدة. قد يقل عرض محدد دون تحسن موازٍ في الوظيفة أو جودة الحياة، وقد يظهر أثر قصير لا يستمر بعد انتهاء العلاج. لذلك تعرض النتائج الأساسية والثانوية والمتابعة والانقطاع والأضرار معًا.</p><p><b>قابلية التطبيق:</b> افحص شدة الحالة، والعمر، والتشخيصات المصاحبة، والأدوية، وتعاطي المواد، والصحة الجسدية، والخطر، واللغة، والقدرة المعرفية والحسية، والدعم والموارد. نتائج تجربة ذات معايير استبعاد صارمة لا تنتقل آليًا إلى خدمة عامة تستقبل حالات أكثر تعقيدًا. ويجب تفسير اختلاف تدريب المعالج والإشراف والالتزام بالبروتوكول.</p><p><b>المقارنة والبدائل:</b> قد تكون المقارنة قائمة انتظار، أو رعاية معتادة، أو تدخلًا نفسيًا آخر، أو دواءً، أو علاجًا مدمجًا. حجم الأثر يعتمد على المقارن؛ لذلك لا توصف النتيجة بأنها كبيرة دون بيان خط الأساس والمقارنة والنتيجة المطلقة. يناقش أيضًا عبء الجلسات والتكلفة والخصوصية وإمكان الوصول واحتمال الانقطاع.</p><p><b>السلامة:</b> لا يفترض أن التدخل النفسي بلا أضرار. يسجل التدهور والضيق غير المحتمل وإعادة تنشيط الصدمة والسلوك الخطر والاعتماد غير الصحي وخرق الخصوصية والانسحاب. تميز الاستجابة المتوقعة المؤقتة عن الضرر، وتوجد آلية تصعيد وإحالة وتنسيق مع الرعاية الطبية والاجتماعية عند الحاجة.</p><p><b>الوفاء والمرونة:</b> يقاس الالتزام بالمكونات الأساسية وكفاءة تقديمها، مع توثيق التعديلات وأسبابها. المرونة الجيدة تستجيب للشخص وتحافظ على وظيفة العلاج؛ أما حذف المكونات الصعبة دون مبرر فقد يحول التدخل إلى اسم تجاري بلا مضمون. تستخدم الإشرافات ومراجعة الجلسات والنتائج لدعم الجودة لا للعقاب.</p><p><b>قرار مشترك قابل للمراجعة:</b> يشرح المختص الخيارات وعدم اليقين والمتطلبات والبدائل، ثم يتفق مع الشخص على أهداف ومؤشرات وموعد مراجعة. عند غياب التحسن أو ظهور ضرر تعاد صياغة الحالة وتفحص جودة التنفيذ والتشخيص والعوائق، ولا يلقى اللوم تلقائيًا على المستفيد.</p>"""
    else:
        content = f"""<p><b>بروتوكول القراءة المنهجية:</b> تبدأ قراءة «{title}» بالسؤال الذي صمم المنهج للإجابة عنه. لا يوجد تصميم أفضل مطلقًا؛ توجد ملاءمة أقوى أو أضعف للسؤال. حدد هل المطلوب وصف انتشار، أو تقدير ارتباط، أو اختبار أثر سببي، أو تقييم دقة، أو بناء أداة، أو تركيب أدلة، ثم افحص هل يسمح التصميم والاستدلال بالإجابة المعلنة.</p><p><b>قبل جمع البيانات:</b> توثق الفرضيات والنتائج الأساسية والسكان والمتغيرات وخطة العينة والتحليل ومعايير الاستبعاد. التسجيل المسبق لا يمنع الاستكشاف، لكنه يفصل ما خطط له عما اكتشف بعد رؤية البيانات. وتوثق جميع التعديلات مع أسبابها وتوقيتها حتى لا تتحول المرونة التحليلية إلى انتقاء نتائج.</p><p><b>جودة البيانات:</b> افحص مصدر البيانات وطريقة القياس والتدريب والمعايرة واللغة والتوقيت والخصوصية. البيانات الكثيرة لا تعوض قياسًا غير صالح أو اختيارًا منحازًا. توثق القيم الشاذة والتكرار والأخطاء والبيانات المفقودة، وتطبق قواعد التنظيف دون استخدام المعرفة بالنتيجة لتغييرها انتقائيًا.</p><p><b>التحليل والتقدير:</b> يعرض حجم الأثر وفاصل الثقة والنتائج المطلقة، لا قيمة الاحتمال وحدها. تفحص الافتراضات والتفاعلات والعناقيد والتكرار وتعدد الاختبارات. تميز التحليلات الأساسية عن الحساسية والفرعية، ويحذر من تحويل النتيجة غير الدالة إلى إثبات للتكافؤ أو غياب الأثر.</p><p><b>التحيز وقابلية النقل:</b> يحدد كل مصدر تحيز محتمل واتجاهه وحجمه التقريبي، وتناقش الإرباكات والاختيار والقياس والفقد والإبلاغ الانتقائي. بعد الصلاحية الداخلية تأتي قابلية التطبيق: هل السكان والسياق والتدخل والنتائج مشابهة للسياق الذي ستستخدم فيه الخلاصة؟</p><p><b>الشفافية والتكرار:</b> تستخدم إرشادات الإبلاغ المناسبة، وتنشر المواد والقاموس البرمجي والكود والبيانات المجهلة عندما تسمح الأخلاقيات والقانون. لا يعني توافر الكود صحة التحليل، لكنه يسمح بالمراجعة. وتعد النتائج المتكررة في فرق مستقلة ومع تصميمات متقاربة أقوى من نتيجة منفردة مثيرة.</p><p><b>الخلاصة المنضبطة:</b> تصاغ النتيجة ضمن السكان والزمن والمقارنة والنتيجة المقاسة، وتذكر القيود وعدم اليقين وما قد يغير القرار. عند اختلاف الدراسات لا يؤخذ المتوسط فقط؛ تفحص مصادر التباين وجودة كل دراسة وعدم المباشرة واحتمال تحيز النشر.</p>"""
    content += "<p><b>قاعدة التحديث والتحقق:</b> تسجل الصفحة تاريخ البحث وأسباب اختيار المصادر وما تغير بين الإصدارات. وعند ظهور إرشاد أحدث أو سحب دراسة أو تصحيحها أو تغير جوهري في التوصيات، تبدأ مراجعة مبكرة ولا ينتظر موعد التحديث الدوري. تراجع الروابط والمصطلحات والترجمات والادعاءات الكمية، ويظل الفرق واضحًا بين النص المنقول والتلخيص والاستنتاج التحريري. كما تحفظ الملاحظات المخالفة والنتائج السلبية لأنها ضرورية لتقدير التوازن الحقيقي للدليل.</p>"
    return base.panel("reference-use", "منهج الاستخدام المرجعي المتقدم", content)


def enhance(site: Path) -> dict:
    # The v400 renderer establishes structure, governance and deduplication.
    # Its preliminary depth floor is lowered only inside this wrapper; the
    # final v401 contract is enforced after the category-specific depth pass.
    base.MIN_WORDS = 650
    report = base.enhance(site)
    counts: dict[str, int] = {}
    for section_slug, section in academic.SECTIONS.items():
        for item in section["entries"]:
            route = f"/library/{section_slug}/{item['slug']}/"
            path = site / route.strip("/") / "index.html"
            source = path.read_text(encoding="utf-8")
            if source.count('href="#governance"') != 1:
                raise SystemExit({"missing_governance_toc": route})
            source = source.replace(
                '<a href="#governance">الحوكمة</a>',
                '<a href="#reference-use">الاستخدام المرجعي</a><a href="#governance">الحوكمة</a>',
                1,
            )
            marker = "</article></div></main>"
            if source.count(marker) != 1:
                raise SystemExit({"academic_article_marker_failed": route, "count": source.count(marker)})
            source = source.replace(marker, appendix(section_slug, item) + marker, 1)
            path.write_text(source, encoding="utf-8")
            count = base.words(source)
            if count < MIN_WORDS:
                raise SystemExit({"academic_reference_depth_failed": route, "words": count})
            if source.count('id="reference-use"') != 1 or source.count('class="governance-grid"') != 1:
                raise SystemExit({"academic_reference_structure_failed": route})
            counts[route] = count

    report.update(
        {
            "version": VERSION,
            "minimum_entry_words": min(counts.values()),
            "depth_pass": "category-specific-reference-use",
            "generated_reference_pages": len(counts),
        }
    )
    if len(counts) != 80 or report["minimum_entry_words"] < MIN_WORDS:
        raise SystemExit({"academic_reference_v401_contract_failed": report})
    api = site / "api"
    (api / "academic-library-reference-v401.json").write_text(
        json.dumps(report, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    return report


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("site", type=Path)
    args = parser.parse_args()
    if not args.site.is_dir():
        raise SystemExit(f"Missing site directory: {args.site}")
    print(json.dumps(enhance(args.site.resolve()), ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
